// @pit: {"label": "Commit with wrapped body, push, open PR, wait for CI"}
async ({ shell: { exec, execFile } }) => {
  await exec(`git add -A && git commit -q -m "fix(extensions): let npm 12 install git specs with --allow-git=root" -m "npm 12 defaults allow-git to none, so it refused extensions such as
github:cv/pit#v0.37.0. pi-action now passes --allow-git=root, unless the
environment sets npm_config_allow_git." -m "Refs #85" && git push -q -u origin fix/85-allow-git`, { timeoutMs: 200000, raise: true });
  const url = (await execFile("gh", ["pr", "create", "--base", "main", "--head", "fix/85-allow-git", "--title", "fix(extensions): let npm 12 install git specs with --allow-git=root", "--body", `Refs #85.

npm 12 defaults \`allow-git\` to \`none\`. When a workflow upgrades npm, pi-action fails to install git specs such as \`github:cv/pit#v0.37.0\` with \`EALLOWGIT\` (see cv/pit#384).

## Changes
- \`npm install\` for \`extensions\` (and skill packages) now gets \`--allow-git=root\`. npm installs the git specs of the input, but not git dependencies of those packages. npm 11, the version on the runners, already supports the flag; its default is \`all\`.
- If the environment sets \`npm_config_allow_git\` (any case), pi-action leaves the flag out, so the user's setting wins.
- \`docs/extensions.md\` describes this under Installation.

Checked: \`npm run check\` passes. The extension tests also pass with npm 12.2.2 on \`PATH\`. With npm 12 and \`--allow-git=root\`, \`npm install github:cv/pit#v0.37.0\` succeeds; without it, npm refuses.`])).stdout.trim();
  await new Promise(r => setTimeout(r, 30000));
  const c = (await exec(`gh pr checks fix/85-allow-git --watch --interval 15 2>&1 | tail -3`, { timeoutMs: 240000 })).stdout;
  return { url, c };
}
